     const onMessage = (e: MessageEvent) => { if (e.data?.type !== 'open-url') return; const day = new URLSearchParams(String(e.data.url).split('?')[1] || '').get('day'); if (day && dateSchema.safeParse(day).success) { history.replaceState(null, '', '/?day=' + day); setPage('calendar'); setDayKey(k => k + 1); } else if (String(e.data.url).includes('focus=1')) { setPage('focus'); } };
     const seen = () => { if (document.visibilityState === 'visible') navigator.serviceWorker.controller?.postMessage({ type: 'seen' }); };
