/* ---------- Tìm trong nhật ký (11) ---------- */
const fold = (t: string) => t.normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/đ/g, 'd').replace(/Đ/g, 'D').toLowerCase();
function JournalHistory({ selected, onPick }: { selected: string; onPick: (d: string) => void }) {
 const { state } = useApp(); const [q, setQ] = useState(''); const [mood, setMood] = useState('');
 const all = Object.entries(state.journals).sort(([a], [b]) => b.localeCompare(a)); const needle = fold(q.trim());
 const list = all.filter(([d, j]) => (!mood || j.mood === mood) && (!needle || fold(j.text).includes(needle) || d.includes(q.trim()) || fold(dateLabel(d)).includes(needle)));
 const snippet = (text: string) => { if (!needle) return text; const i = fold(text).indexOf(needle); return i > 40 ? '…' + text.slice(i - 30) : text; };
 return <Panel title="Những ngày đã qua">{all.length ? <>
  <div className="journal-search"><label className="field"><span className="sr-only">Tìm trong nhật ký</span><input type="search" value={q} onChange={e => setQ(e.target.value)} placeholder="Tìm một từ, một kỷ niệm…" enterKeyHint="search" /></label><label className="field"><span className="sr-only">Lọc theo cảm xúc</span><SoftSelect value={mood} onChange={e => setMood(e.target.value)}><option value="">Mọi cảm xúc</option>{['Vui', 'Ổn', 'Bình thường', 'Mệt', 'Buồn'].map(m => <option key={m} value={m}>{m}</option>)}</SoftSelect></label></div>
  {(q || mood) && <small className="journal-count">{list.length ? `Tìm thấy ${list.length} trang` : 'Chưa thấy trang nào phù hợp.'}</small>}
  <div className="journal-history">{list.map(([d, j]) => <button key={d} className={d === selected ? 'selected' : ''} onClick={() => onPick(d)}><span className="row spread"><strong>{dateLabel(d, true)}</strong><span className="pill">{j.mood}</span></span><p>{j.text ? snippet(j.text) : 'Một cảm xúc đã được lưu lại.'}</p></button>)}</div>
 </> : <Empty icon={BookOpen} title="Chưa có trang nhật ký">Không cần viết hay. Chỉ cần là điều Mihu muốn nhớ.</Empty>}</Panel>;
}
/* ---------- Tên việc trong thông báo (12) ---------- */
function ReminderTitleToggle() {
 const { state, save, busy, notify, preview } = useApp(); const on = state.settings.reminderTitle;
 return <div className="reminder-privacy"><label className="check-label"><input type="checkbox" checked={on} disabled={busy || preview} onChange={async e => { try { await save({ type: 'settings.save', settings: { ...state.settings, reminderTitle: e.target.checked } }); } catch (err) { notify((err as Error).message, 'error'); } }} />Hiện tên việc trong thông báo</label><small>{on ? 'Thông báo ghi rõ tên việc và giờ. Người nhìn màn hình khóa cũng đọc được.' : 'Đang ẩn tên việc: thông báo chỉ báo giờ, không lộ nội dung lịch.'}</small></div>;
}

/* ---------- Tập trung (Pomodoro) ---------- */
let audio: AudioContext | null = null;
/** iOS only lets a page play sound after a tap, so the context is opened on Start/Resume. */
function unlockAudio() { try { audio ??= new AudioContext(); if (audio.state === 'suspended') void audio.resume(); } catch { /* no audio */ } }
function chime() { if (!audio) return; const t0 = audio.currentTime; [784, 988, 1175].forEach((f, i) => { const o = audio!.createOscillator(); const g = audio!.createGain(); o.type = 'sine'; o.frequency.value = f; g.gain.setValueAtTime(0, t0 + i * 0.18); g.gain.linearRampToValueAtTime(0.18, t0 + i * 0.18 + 0.02); g.gain.exponentialRampToValueAtTime(0.001, t0 + i * 0.18 + 0.9); o.connect(g).connect(audio!.destination); o.start(t0 + i * 0.18); o.stop(t0 + i * 0.18 + 1); }); try { navigator.vibrate?.([120, 80, 120]); } catch { } }
function useNow(active: boolean) { const [now, setNow] = useState(() => Date.now()); useEffect(() => { if (!active) return; const t = setInterval(() => setNow(Date.now()), 500); return () => clearInterval(t); }, [active]); return now; }

/** Finishes the running timer when it reaches zero, wherever Mihu is in the app. */
function FocusEngine() {
 const { state, save, notify, today } = useApp(); const a = state.focus.active; const now = useNow(!!a && a.pausedAt === null); const done = useRef(''); const [retry, setRetry] = useState(0);
 const left = a ? focusRemaining(a, now) : 0;
 useEffect(() => { const base = 'Mihu’s Corner'; document.title = a ? `${a.pausedAt !== null ? '⏸' : a.mode === 'focus' ? '🌻' : '☕'} ${clock(left)} · ${base}` : base; }, [a, left]);
 useEffect(() => {
  if (!a || a.pausedAt !== null || left > 0 || done.current === a.id) return;
  done.current = a.id; const finished = a;
  (async () => {
   try { await save({ type: 'focus.complete', id: finished.id }); } catch { done.current = ''; setTimeout(() => setRetry(n => n + 1), 5000); return; } // try again shortly (busy, offline or clock drift)
   chime();
   if (finished.mode !== 'focus') { notify('Hết giờ nghỉ rồi. Sẵn sàng cho phiên tiếp theo nhé!'); return; }
   const f = state.focus; const next = nextBreak({ ...f, cycle: f.cycle + 1 });
   notify(`🌻 Xong ${finished.minutes} phút tập trung! Nghỉ ${f.settings[next]} phút nhé.`);
   const task = finished.taskId ? tasksOn(state, finished.taskDate).find(t => t.id === finished.taskId) : undefined;
   if (task && !task.done && finished.taskDate <= today && await askConfirmation(`Mihu đã xong “${task.title}” chưa? Đánh dấu hoàn thành luôn nhé?`)) { try { await save({ type: 'task.toggle', id: task.id, on: finished.taskDate, done: true }); } catch (e) { notify((e as Error).message, 'error'); } }
   if (f.settings.autoBreak) { try { await save({ type: 'focus.start', mode: next, taskId: '', taskDate: '' }); } catch { } }
  })();
 }, [a, left, retry]); // eslint-disable-line react-hooks/exhaustive-deps
 return null;
}

function FocusRing({ left, total, mode, paused }: { left: number; total: number; mode: FocusMode; paused: boolean }) {
 const r = 108, c = 2 * Math.PI * r; const p = total ? 1 - left / total : 0;
 return <div className={'focus-ring mode-' + mode + (paused ? ' paused' : '')} role="timer" aria-live="off" aria-label={`Còn ${clock(left)}`}>
  <svg viewBox="0 0 240 240" aria-hidden="true"><circle cx="120" cy="120" r={r} className="track" /><circle cx="120" cy="120" r={r} className="bar" strokeDasharray={c} strokeDashoffset={c * (1 - p)} transform="rotate(-90 120 120)" /></svg>
  <div><strong>{clock(left)}</strong><span>{paused ? 'Đang tạm dừng' : modeLabel[mode]}</span></div>
 </div>;
}

function FocusPage() {
 const { state, today, save, busy, notify, preview } = useApp(); const f = state.focus; const a = f.active; const now = useNow(!!a && a.pausedAt === null);
 const [mode, setMode] = useState<FocusMode>('focus');
 const prev = useRef(a); useEffect(() => { const p = prev.current; prev.current = a; if (p && !a) setMode(p.mode === 'focus' ? nextBreak(f) : 'focus'); }, [a]); // eslint-disable-line react-hooks/exhaustive-deps
 const [taskKey, setTaskKey] = useState(''); const [settings, setSettings] = useState(false);
 const [wake, setWake] = useState(() => { try { return localStorage.getItem('mihu-wake') === '1'; } catch { return false; } });
 const todays = tasksOn(state, today).filter(t => !t.done);
 const running = !!a && a.pausedAt === null;
 // Optional: keep the screen on while a timer runs (iOS 16.4+, Chrome).
 useEffect(() => { if (!wake || !running || !('wakeLock' in navigator)) return; let lock: WakeLockSentinel | null = null; let alive = true; const get = () => { if (document.visibilityState === 'visible') navigator.wakeLock.request('screen').then(l => { if (alive) lock = l; else void l.release(); }).catch(() => { }); }; get(); document.addEventListener('visibilitychange', get); return () => { alive = false; document.removeEventListener('visibilitychange', get); void lock?.release(); }; }, [wake, running]);
 async function run(c: Command) { unlockAudio(); try { await save(c); } catch (e) { notify((e as Error).message, 'error'); } }
 const pick = todays.find(t => t.key === taskKey);
 const left = a ? focusRemaining(a, now) : f.settings[mode] * 60000; const total = a ? a.minutes * 60000 : left;
 const t = focusToday(f.log, today); const bars = weekBars(f.log, today); const max = Math.max(...bars.map(b => b.minutes), f.settings.goal ? Math.round(f.settings.goal / 2) : 30, 30);
 const streak = focusStreak(f.log, today); const tasks = focusByTask(f.log, addDays(today, -6)); const goalPct = f.settings.goal ? Math.min(100, Math.round(t.minutes / f.settings.goal * 100)) : 0;
 const cycleDots = Array.from({ length: f.settings.every }, (_, i) => i < (f.cycle % f.settings.every || (f.cycle && nextBreak(f) === 'long' ? f.settings.every : 0)));
 return <div className="focus-grid">
  <Panel className="focus-main">
   {!a && <div className="segmented focus-modes" role="tablist">{(['focus', 'short', 'long'] as const).map(m => <button key={m} role="tab" aria-selected={mode === m} className={mode === m ? 'active' : ''} onClick={() => setMode(m)}>{modeLabel[m]} · {f.settings[m]}′</button>)}</div>}
   <FocusRing left={left} total={total} mode={a?.mode || mode} paused={!!a && a.pausedAt !== null} />
   <div className="focus-cycle" aria-label={`Phiên ${f.cycle % f.settings.every + 1} trong vòng ${f.settings.every} phiên`}>{cycleDots.map((d, i) => <span key={i} className={d ? 'on' : ''} />)}</div>
   {a ? <p className="focus-label">{a.mode === 'focus' ? (a.label ? <>Đang làm: <strong>{a.label}</strong></> : 'Một phiên tập trung tự do') : 'Thả lỏng vai, uống chút nước, nhìn ra xa một chút nhé.'}</p>
    : mode === 'focus' && <label className="field focus-task"><span>Mihu sẽ tập trung cho việc gì?</span><SoftSelect value={taskKey} onChange={e => setTaskKey(e.target.value)}><option value="">Không gắn với việc nào</option>{todays.map(x => <option key={x.key} value={x.key}>{x.time ? x.time + ' · ' : ''}{x.title}</option>)}</SoftSelect></label>}
   <div className="focus-actions">{!a ? <button className="button primary big" disabled={busy || preview} onClick={() => run({ type: 'focus.start', mode, taskId: mode === 'focus' && pick ? pick.id : '', taskDate: mode === 'focus' && pick ? pick.occurrenceDate : '' })}><Play size={20} />Bắt đầu</button>
    : <>{a.pausedAt !== null ? <button className="button primary big" disabled={busy} onClick={() => run({ type: 'focus.resume' })}><Play size={20} />Tiếp tục</button> : <button className="button primary big" disabled={busy} onClick={() => run({ type: 'focus.pause' })}><Pause size={20} />Tạm dừng</button>}
     <button className="button" disabled={busy} onClick={async () => { if (a.mode === 'focus' && !await askConfirmation('Dừng phiên này? Thời gian đã tập trung (từ 1 phút) vẫn được ghi lại.')) return; await run({ type: 'focus.stop' }); if (a.mode !== 'focus') setMode('focus'); }}>{a.mode === 'focus' ? <><Square size={16} />Dừng</> : <><SkipForward size={16} />Bỏ qua nghỉ</>}</button></>}</div>
   <div className="focus-tools"><label className="check-label"><input type="checkbox" checked={wake} onChange={e => { setWake(e.target.checked); try { localStorage.setItem('mihu-wake', e.target.checked ? '1' : '0'); } catch { } }} />Giữ màn hình sáng khi đang chạy</label><button className="text-button" onClick={() => setSettings(true)}><Settings2 size={16} />Tùy chỉnh</button></div>
   <p className="support-line">Có thể khóa máy hoặc chuyển ứng dụng. Nếu đã bật nhắc việc, Mihu sẽ nhận thông báo khi hết giờ (có thể trễ khoảng 1 phút).</p>
  </Panel>
  <div className="stack">
   <Panel title="Hôm nay">
    <div className="focus-today"><div><strong>{minutesLabel(t.minutes)}</strong><small>{f.settings.goal ? `mục tiêu ${minutesLabel(f.settings.goal)}` : 'đã tập trung'}</small></div><div><strong>{t.sessions}</strong><small>phiên trọn vẹn</small></div><div><strong><Flame size={18} />{streak}</strong><small>ngày liên tiếp</small></div></div>
    {f.settings.goal > 0 && <><Progress value={goalPct} /><p className="support-line">{goalPct >= 100 ? '🌻 Đạt mục tiêu hôm nay rồi, Mihu giỏi lắm!' : `Còn ${minutesLabel(Math.max(0, f.settings.goal - t.minutes))} nữa là chạm mục tiêu.`}</p></>}
   </Panel>
   <Panel title="7 ngày qua">
    <div className="focus-bars" role="img" aria-label={'Số phút tập trung 7 ngày qua: ' + bars.map(b => `${dateLabel(b.date, true)} ${b.minutes} phút`).join(', ')}>{bars.map(b => <div key={b.date} className={b.date === today ? 'today' : ''} title={`${dateLabel(b.date, true)}: ${minutesLabel(b.minutes)}`}><small className="value">{b.minutes || ''}</small><span style={{ height: Math.max(b.minutes ? 4 : 0, b.minutes / max * 100) + '%' }} /><small>{['CN', 'T2', 'T3', 'T4', 'T5', 'T6', 'T7'][new Date(b.date + 'T12:00:00Z').getUTCDay()]}</small></div>)}</div>
    <p className="support-line">Tổng tuần: {minutesLabel(bars.reduce((x, b) => x + b.minutes, 0))}</p>
   </Panel>
   <Panel title="Thời gian đã dành cho">{tasks.length ? <div className="focus-tasks">{tasks.map(x => <div key={x.label} className="row spread"><span>{x.label}</span><strong>{minutesLabel(x.minutes)}</strong></div>)}</div> : <p className="support-line">Gắn phiên tập trung với một việc trong lịch để thấy thời gian đi đâu.</p>}</Panel>
  </div>
  {settings && <FocusSettingsForm onClose={() => setSettings(false)} />}
 </div>;
}

function FocusSettingsForm({ onClose }: { onClose: () => void }) {
 const { state, save } = useApp(); const s = state.focus.settings; const [error, setError] = useState('');
 const num = (name: keyof FocusSettings, label: string, min: number, max: number, hint?: string) => <label className="field">{label}<input name={name} type="number" inputMode="numeric" required min={min} max={max} step={1} defaultValue={s[name] as number} />{hint && <small>{hint}</small>}</label>;
 return <Modal title="Tùy chỉnh tập trung" onClose={onClose}><form onSubmit={async e => { e.preventDefault(); const f = new FormData(e.currentTarget); const n = (k: string) => Number(f.get(k)); try { await save({ type: 'focus.settings', settings: { focus: n('focus'), short: n('short'), long: n('long'), every: n('every'), goal: n('goal'), autoBreak: f.get('autoBreak') === 'on' } }); onClose(); } catch (err) { setError((err as Error).message); } }}>
  <div className="form-grid">{num('focus', 'Tập trung (phút)', 5, 120)}{num('short', 'Nghỉ ngắn (phút)', 1, 30)}</div>
  <div className="form-grid">{num('long', 'Nghỉ dài (phút)', 5, 60)}{num('every', 'Nghỉ dài sau mỗi', 2, 8, 'phiên tập trung')}</div>
  {num('goal', 'Mục tiêu mỗi ngày (phút)', 0, 960, '0 nếu không đặt mục tiêu')}
  <label className="check-label"><input type="checkbox" name="autoBreak" defaultChecked={s.autoBreak} />Tự bắt đầu giờ nghỉ khi hết phiên tập trung</label>
  {error && <p className="error-banner" role="alert">{error}</p>}
  <div className="form-actions"><button type="button" className="button" onClick={onClose}>Để sau</button><Submit /></div>
 </form></Modal>;
}

/** Small timer shown on other pages while a session runs. */
function FocusPill({ open }: { open: () => void }) {
 const { state } = useApp(); const a = state.focus.active; const now = useNow(!!a && a.pausedAt === null); if (!a) return null;
 return <button className={'focus-pill mode-' + a.mode} onClick={open} aria-label="Mở góc tập trung">{a.pausedAt !== null ? <Pause size={15} /> : a.mode === 'focus' ? <Timer size={15} /> : <Coffee size={15} />}{clock(focusRemaining(a, now))}</button>;
}

function FocusWidget({ open }: { open: () => void }) {
 const { state, today, save, busy, notify, preview } = useApp(); const f = state.focus; const t = focusToday(f.log, today); const a = f.active; const now = useNow(!!a && a.pausedAt === null);
 return <Panel title="Tập trung hôm nay" action={<button className="text-button" onClick={open}>Mở góc tập trung</button>}>
  <div className="row spread"><span>{minutesLabel(t.minutes)}{f.settings.goal ? ` / ${minutesLabel(f.settings.goal)}` : ''}</span><small>{t.sessions} phiên</small></div>
  {f.settings.goal > 0 && <Progress value={Math.min(100, t.minutes / f.settings.goal * 100)} />}
  {a ? <button className="button full" onClick={open}><Timer size={16} />{modeLabel[a.mode]} · còn {clock(focusRemaining(a, now))}</button>
   : <button className="button full" disabled={busy || preview} onClick={async () => { unlockAudio(); try { await save({ type: 'focus.start', mode: 'focus', taskId: '', taskDate: '' }); open(); } catch (e) { notify((e as Error).message, 'error'); } }}><Play size={16} />Bắt đầu {f.settings.focus} phút</button>}
 </Panel>;
}

/* ---------- Ô nhập tiền có dấu chấm ---------- */
const MONEY_MAX = 1_000_000_000_000;
const groupDots = (digits: string) => digits.replace(/\B(?=(\d{3})+(?!\d))/g, '.');
/** "233 nghìn 345 đồng", "1 triệu 500 nghìn đồng": read-back that makes a missing or extra 0 obvious. */
export function moneyWords(n: number) {
 if (!n) return '0 đồng'; const parts: string[] = []; let rest = n;
 for (const [size, name] of [[1e9, 'tỷ'], [1e6, 'triệu'], [1e3, 'nghìn']] as const) { const q = Math.floor(rest / size); if (q) { parts.push(`${q.toLocaleString('vi-VN')} ${name}`); rest -= q * size; } }
 if (rest) parts.push(String(rest)); return parts.join(' ') + ' đồng';
}
/**
 * Money field that shows 1.250.000 while typing (dots every three digits) and submits the plain
 * number under `name`, so forms read it exactly as before.
 */
function MoneyInput({ name, defaultValue, required = false, min = 0, autoFocus, placeholder }: { name: string; defaultValue?: number; required?: boolean; min?: number; autoFocus?: boolean; placeholder?: string }) {
 const [digits, setDigits] = useState(defaultValue ? String(Math.round(defaultValue)) : ''); const wordsId = useId(); const ref = useRef<HTMLInputElement>(null); const caret = useRef<number | null>(null);
 useEffect(() => {
  const el = ref.current; if (!el) return;
  const n = Number(digits || 0);
  el.setCustomValidity(required && !digits ? 'Mihu nhập số tiền nhé.' : digits && n < min ? `Số tiền phải từ ${groupDots(String(min))} ₫ trở lên.` : n > MONEY_MAX ? 'Số tiền quá lớn.' : '');
  // Keep the cursor after the same digit once dots are added or removed.
  if (caret.current !== null && document.activeElement === el) { let seen = 0, pos = 0; const text = el.value; while (pos < text.length && seen < caret.current) { if (/\d/.test(text[pos])) seen++; pos++; } el.setSelectionRange(pos, pos); caret.current = null; }
 }, [digits, required, min]);
 return <span className="money-input">
  <span className="money-box"><input ref={ref} type="text" inputMode="numeric" autoComplete="off" enterKeyHint="done" autoFocus={autoFocus} placeholder={placeholder || '0'} value={groupDots(digits)} required={required} aria-describedby={wordsId}
   onChange={e => { const before = e.target.value.slice(0, e.target.selectionStart ?? e.target.value.length).replace(/\D/g, '').replace(/^0+(?=\d)/, '').length; const next = e.target.value.replace(/\D/g, '').replace(/^0+(?=\d)/, '').slice(0, 13); caret.current = Math.min(before, next.length); setDigits(next); }} /><span aria-hidden="true">₫</span></span>
  <input type="hidden" name={name} value={digits} />
  {digits && <small id={wordsId} className="money-words">{moneyWords(Number(digits))}</small>}
 </span>;
}

/** How full the account's storage is; warns early so nothing ever stops saving by surprise. */
function StorageMeter({ usage }: { usage: { bytes: number; limit: number } }) {
 const pct = Math.min(100, Math.round(usage.bytes / usage.limit * 100)); const size = (b: number) => b >= 1e6 ? (b / 1e6).toFixed(1).replace('.', ',') + ' MB' : Math.max(1, Math.round(b / 1e3)) + ' KB';
 return <Panel title="Bộ nhớ của góc nhỏ"><div className="row spread"><span>Đã dùng {pct}%</span><small>{size(usage.bytes)} / {size(usage.limit)}</small></div><div className={pct >= 90 ? 'storage-bar full' : pct >= 70 ? 'storage-bar near' : 'storage-bar'}><Progress value={Math.max(pct, 1)} /></div>
  <p className="support-line">{pct >= 90 ? 'Bộ nhớ gần đầy. Mihu xóa bớt nhật ký, khoản chi hoặc việc cũ để lưu tiếp nhé.' : pct >= 70 ? 'Bộ nhớ đã dùng khá nhiều. Mihu có thể xóa bớt những trang không cần giữ.' : 'Còn rất nhiều chỗ cho những điều Mihu muốn lưu lại.'}</p></Panel>;
}
